starter:
function isMultiple(n, d) {
  // your code here
}

console.log(isMultiple(10, 5));

solution:
function isMultiple(n, d) {
  // % gives the remainder of n / d.
  // If nothing is left over, n is a multiple of d.
  return n % d === 0;
}

console.log(isMultiple(10, 5));

starter:
function average(a, b, c) {
  // your code here
}

console.log(average(4, 5, 6));

solution:
function average(a, b, c) {
  // The parentheses make the sum happen before the division.
  // Without them, only c would be divided by 3.
  return (a + b + c) / 3;
}

console.log(average(4, 5, 6));

alternatives:
function average(a, b, c) {
  let sum = a + b + c;
  return sum / 3;
}

console.log(average(4, 5, 6));

