function sign(n) {
  // your code here
}

console.log(sign(-3));

solution:
function sign(n) {
  // If the first condition is false, a second ternary decides
  // between "negative" and "zero".
  return n > 0 ? "positive" : n < 0 ? "negative" : "zero";
}

console.log(sign(-3));

alternatives:
function sign(n) {
  if (n > 0) {
    return "positive";
  } else if (n < 0) {
    return "negative";
  }
  return "zero";
}

console.log(sign(-3));

