statement.en:
In a web page you would ask `let answer = prompt("How old are you?");`. Write a function `nextYear(answer)` that receives that answer (a string, or `null` if the user clicked Cancel) and returns:
- `"Cancelled"` if `answer` is `null`;
- `"Please type your age"` if it's an empty string;
- otherwise, `"Next year you will be X"`, where X is the age plus 1.
Example: `nextYear("20")` returns `"Next year you will be 21"`.

statement.es:
En una página web preguntarías `let answer = prompt("How old are you?");`. Escribe una función `nextYear(answer)` que reciba esa respuesta (un string, o `null` si el usuario pulsó Cancelar) y devuelva:
- `"Cancelled"` si `answer` es `null`;
- `"Please type your age"` si es un string vacío;
- en otro caso, `"Next year you will be X"`, donde X es la edad más 1.
Ejemplo: `nextYear("20")` devuelve `"Next year you will be 21"`.

starter:
function nextYear(answer) {
  // your code here
}

console.log(nextYear("20"));

solution:
function nextYear(answer) {
  // Cancel gives null: check it before using the text.
  if (answer === null) {
    return "Cancelled";
  }
  // OK with an empty box gives "".
  if (answer === "") {
    return "Please type your age";
  }
  // prompt always returns text: convert it before adding,
  // or "20" + 1 would be "201".
  return "Next year you will be " + (Number(answer) + 1);
}

console.log(nextYear("20"));

alternatives:
function nextYear(answer) {
  if (answer === null) return "Cancelled";
  if (answer === "") return "Please type your age";
  let age = Number(answer);
  return `Next year you will be ${age + 1}`;
}

console.log(nextYear("20"));

statement.en:
Write a function `ticketPrice(age, isStudent)` that returns the price of a cinema ticket:
- children under 4 don't pay: `0`;
- people under 18 or students pay `5`;
- everyone else pays `9`.
Example: `ticketPrice(25, true)` returns `5` and `ticketPrice(25, false)` returns `9`.

statement.es:
Escribe una función `ticketPrice(age, isStudent)` que devuelva el precio de una entrada de cine:
- los menores de 4 años no pagan: `0`;
- los menores de 18 o los estudiantes pagan `5`;
- el resto paga `9`.
Ejemplo: `ticketPrice(25, true)` devuelve `5` y `ticketPrice(25, false)` devuelve `9`.

starter:
function ticketPrice(age, isStudent) {
  // your code here
}

console.log(ticketPrice(25, true));

solution:
function ticketPrice(age, isStudent) {
  // The free case goes first: a 3-year-old is also under 18.
  if (age < 4) {
    return 0;
  }
  // One of the two conditions is enough, so we use ||.
  if (age < 18 || isStudent) {
    return 5;
  }
  return 9;
}

console.log(ticketPrice(25, true));

alternatives:
function ticketPrice(age, isStudent) {
  return age < 4 ? 0 : age < 18 || isStudent ? 5 : 9;
}

console.log(ticketPrice(25, true));
